  canvasMetrics(){const rect=this.canvas.getBoundingClientRect(),fit=Math.min(rect.width/this.engine.width,rect.height/this.engine.height),scale=fit*this.camera.zoom,drawX=rect.width/2+this.camera.panX-this.engine.width*scale/2,drawY=rect.height/2+this.camera.panY-this.engine.height*scale/2;return{rect,fit,scale,drawX,drawY};}
