app.boot().catch(error=>{console.error(error);document.querySelector('#app').innerHTML=`<div style="padding:40px;font-family:sans-serif"><h1>ВЕЩЕСТВО</h1><p>Лаборатория не смогла восстановить состояние.</p><button onclick="location.reload()">Перезапустить</button></div>`;});

